/*
 * A007952  Generated by a sieve: keep first number, drop every 2nd, keep
 *          first, drop every 3rd, keep first, drop every 4th, etc.
 * https://oeis.org/A007952
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(n) is the rank at which value n first appears in the
 *            Tchoukaillon sieve. * Computed as: i = 0; for j from n down to
 *            1: i = 1 + i + floor(i / j)
 * Range:     u8 n <= 26, u16 n <= 453, u32 n <= 7549, u64 n <= 7549,
 *            u128 n <= 7549, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n) {
    seq_t i = 0;
    for (idx_t j = n; j > 0; j--) {
        i = 1 + i + i / j;
    }
    return i;
}
